<?php
namespace App\Http\Controllers;use App\Models\Branch;use App\Models\ContactMessage;use App\Models\ContactPage;use Illuminate\Http\RedirectResponse;use Illuminate\Http\Request;use Illuminate\View\View;
class ContactPageController extends Controller {public function index():View{return view('pages.contact',['settings'=>ContactPage::first(),'branches'=>Branch::where('is_active',true)->with('city')->orderBy('name')->get()]);}public function store(Request $r):RedirectResponse{$data=$r->validate(['name'=>['required','string','max:255'],'email'=>['required','email','max:255'],'phone'=>['required','string','max:50'],'subject'=>['required','string','max:255'],'message'=>['required','string','max:5000'],'agreement'=>['accepted']]);unset($data['agreement']);ContactMessage::create($data);return back()->with('status','Thank you! Your message has been received.');}}
